`timescale 1ns/1ps
// ch14_alu8_tb.v -- self-checking vector test for alu8.
// Reads packed vectors from ch14_alu8_vectors.dat (generated by
// ch14_alu8_vec_gen.py), applies each, checks result AND all four flags
// with case-equality so an 'x' anywhere counts as a mismatch.
module alu8_tb;
  reg  [7:0] a, b;
  reg  [2:0] op;
  wire [7:0] y;
  wire       z, n, c, v;

  alu8 u(.i_a(a), .i_b(b), .i_op(op), .o_y(y),
         .o_z(z), .o_n(n), .o_c(c), .o_v(v));

  reg [30:0] vec [0:63];          // {op,a,b,y,z,n,c,v} packed, 31 bits
  integer i, errors = 0, checks = 0;
  reg [7:0] ey;
  reg ez, en, ec, ev;

  task check;
    begin
      checks = checks + 1;
      if ({y, z, n, c, v} !== {ey, ez, en, ec, ev}) begin
        errors = errors + 1;
        $display("MISMATCH t=%0d op=%b a=%h b=%h got y=%h z=%b n=%b c=%b v=%b want y=%h z=%b n=%b c=%b v=%b",
                 $time, op, a, b, y, z, n, c, v, ey, ez, en, ec, ev);
      end
    end
  endtask

  initial begin
    $dumpfile("ch14_alu8.vcd");
    $dumpvars(0, alu8_tb);
    $readmemh("ch14_alu8_vectors.dat", vec);
    for (i = 0; i < 64; i = i + 1) begin
      {op, a, b, ey, ez, en, ec, ev} = vec[i];
      #10;
      check;
      $display("t=%0d op=%b a=%h b=%h -> y=%h z=%b n=%b c=%b v=%b",
               $time, op, a, b, y, z, n, c, v);
    end
    if (errors == 0)
      $display("PASS: all %0d vectors match (result + ZN CV flags)", checks);
    else
      $display("FAIL: %0d of %0d vectors wrong", errors, checks);
    $finish;
  end
endmodule
